<script setup lang="ts">
defineI18nRoute(false);definePageMeta({layout:'admin-taiko',middleware:'admin-auth'});useHead({title:'Annual Closed Beta'});
const api=useAdminApiFetch();const {data,refresh,error}=await useAsyncData<any>('beta-dashboard',()=>api('/api/admin/annual-beta'));const selected=ref('');const detail=ref<any>(null);const operationError=ref('');
const fields=['annual_entry_impression','annual_entry_click','beta_invite_gate_view','beta_invite_submit','beta_invite_validated','beta_invite_redeemed','auth_success','binding_success','data_sync_success','annual_build_success','annual_report_complete','annual_poster_open','annual_feedback_submit','annual_data_issue_submit'];
const labels=['Hero Seen','Hero Clicked','Invite Gate','Invite Submitted','Invite Validated','Invite Redeemed','Auth Success','Bound','Synced','Build Success','Report Completed','Poster Opened','Feedback','Data Issues'];
const count=(key:string)=>Number(data.value?.funnel.find((x:any)=>x.event_name===key)?.participants||0);
const has=(p:any,key:string)=>String(p.completed_events||'').split(',').includes(key);
const open=async(p:any)=>{selected.value=p.id;try{detail.value=await api('/api/admin/annual-beta/participant',{query:{id:p.id}});}catch{operationError.value='无法加载时间线';}};
const manage=async(action:string,id:string,level?:number)=>{try{await api('/api/admin/annual-beta/manage',{method:'POST',body:{action,id,level}});await refresh();}catch{operationError.value='操作失败，请重试';}};
const pairs=[['Hero CTR','annual_entry_impression','annual_entry_click'],['Invite submit','annual_entry_click','beta_invite_submit'],['Validate','beta_invite_submit','beta_invite_validated'],['Auth','beta_invite_validated','auth_success'],['Redeem','auth_success','beta_invite_redeemed'],['Binding start','beta_invite_redeemed','binding_start'],['Binding success','binding_start','binding_success'],['Data ready','binding_success','data_sync_success'],['Annual discovery','data_sync_success','annual_entry_ready'],['Build','annual_entry_ready','annual_build_success'],['Report open','annual_build_success','annual_report_open'],['Read complete','annual_report_open','annual_report_complete'],['Poster','annual_report_complete','annual_poster_open']];
const durations=[['Time to Auth','beta_invite_validated','auth_success'],['Time to Binding','beta_invite_redeemed','binding_success'],['Binding Verify','binding_verify_start','binding_success'],['Time to Data Ready','binding_success','data_sync_success'],['Sync → Annual','data_sync_success','annual_entry_ready'],['Cold Build','annual_build_start','annual_build_success'],['Annual Read','annual_report_open','annual_report_complete']];
const duration=(start:string,end:string)=>{const rows=data.value?.times||[];const values=rows.filter((r:any)=>r.event_name===start).flatMap((a:any)=>{const b=rows.find((r:any)=>r.participant_id===a.participant_id&&r.event_name===end);const ms=b?new Date(b.first_at).getTime()-new Date(a.first_at).getTime():-1;return ms>=0?[ms/1000]:[];}).sort((a:number,b:number)=>a-b);return values.length?`${values[Math.floor(values.length/2)].toFixed(1)}s · n=${values.length}`:'—';};
const conversion=(a:string,b:string)=>{const rows=data.value?.times||[];const starts=rows.filter((r:any)=>r.event_name===a);const n=starts.filter((x:any)=>rows.some((y:any)=>y.participant_id===x.participant_id&&y.event_name===b&&new Date(y.first_at)>=new Date(x.first_at))).length;return `${n}/${starts.length}`;};
</script>
<template><div class="admin-page-stack"><h1>Annual Closed Beta</h1><el-button @click="refresh">刷新</el-button><p v-if="error||operationError" role="alert">{{operationError||'无法加载数据'}}</p><template v-if="data"><div class="beta-funnel"><el-card v-for="(field,i) in fields" :key="field"><small>{{labels[i]}}</small><strong>{{count(field)}}</strong></el-card></div><el-card><h2>邀请与激活</h2><p>Invited {{data.invites.length}} · Redeemed {{data.invites.filter((i:any)=>i.status==='redeemed').length}} · Expired {{data.invites.filter((i:any)=>i.status==='expired').length}} · Disabled {{data.invites.filter((i:any)=>i.status==='disabled').length}}</p><p>Self-Service Activation：{{data.activation.activated||0}} / {{data.activation.eligible||0}}（Hero 起步，T0–T2，完成邀请、认证、绑定、同步及报告）</p><p>Insufficient data：{{count('annual_unavailable')}}</p><div class="beta-metrics"><span v-for="[label,a,b] in pairs" :key="label">{{label}} {{conversion(a,b)}}</span><span v-for="[label,a,b] in durations" :key="label">{{label}} p50 {{duration(a,b)}}</span></div></el-card><el-card><h2>Participants</h2><div class="beta-table"><table><thead><tr><th>participant / user</th><th>cohort / invite</th><th>auth</th><th>binding</th><th>sync</th><th>hint</th><th>Hero seen/click</th><th>Annual open/build</th><th>complete/poster</th><th>feedback/issue</th></tr></thead><tbody><tr v-for="p in data.participants" :key="p.id"><td><button @click="open(p)">{{p.id.slice(0,8)}} / {{p.user_id||'guest'}}</button></td><td>{{p.cohort||'—'}} / {{p.invite_id?(p.entitlement_enabled?'redeemed':'disabled'):'—'}}</td><td>{{has(p,'auth_success')?'✓':'—'}}</td><td>{{has(p,'binding_success')?'✓':has(p,'binding_failure')?'failed':has(p,'binding_pending')?'pending':'—'}}</td><td>{{has(p,'data_sync_success')?'✓':has(p,'data_sync_failure')?'failed':'—'}}</td><td>T{{p.hint_level}} <button v-for="n in 3" :key="n" @click="manage('hint',p.id,n)">T{{n}}</button></td><td>{{has(p,'annual_entry_impression')}} / {{has(p,'annual_entry_click')}}</td><td>{{has(p,'annual_report_open')}} / {{has(p,'annual_build_success')?'✓':has(p,'annual_unavailable')?'insufficient':has(p,'annual_build_failure')?'failed':'—'}}</td><td>{{has(p,'annual_report_complete')}} / {{has(p,'annual_poster_open')}}</td><td>{{has(p,'annual_feedback_submit')}} / {{has(p,'annual_data_issue_submit')}}</td></tr></tbody></table></div></el-card><el-card><h2>Invites</h2><div class="beta-table"><table><tr v-for="invite in data.invites" :key="invite.id"><td>{{invite.id.slice(0,8)}}</td><td>{{invite.cohort}}</td><td>{{invite.status}}</td><td>{{invite.expires_at}}</td><td><el-button v-if="!invite.disabled_at" @click="manage('disable_invite',invite.id)">停用</el-button></td></tr></table></div></el-card><el-card v-if="detail"><h2>{{selected}} · Timeline</h2><ol><li v-for="(e,i) in detail.events" :key="i">{{e.occurred_at}} · {{e.event_name}} · {{e.locale}} · {{e.device_class}} <code>{{e.metadata_json}}</code></li></ol><h3>反馈</h3><article v-for="(f,i) in detail.feedback" :key="i"><strong>{{f.kind}} · {{f.category||'survey'}}</strong><pre>{{JSON.stringify(f.answers_json,null,2)}}</pre><small>{{f.context_json}}</small></article></el-card></template></div></template>
<style scoped>.beta-funnel{display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:10px}.beta-funnel strong{display:block;font-size:26px;margin-top:6px}.beta-table{overflow:auto}.beta-table table{border-collapse:collapse;min-width:850px;width:100%}.beta-table th,.beta-table td{padding:10px;text-align:left;border-bottom:1px solid var(--el-border-color)}.beta-table button{min-height:36px;cursor:pointer}.beta-metrics{display:flex;flex-wrap:wrap;gap:16px}pre{white-space:pre-wrap;overflow-wrap:anywhere}</style>
